def refs(page,section):return [{'sourceId':source,'pdfPage':page,'page':page,'printedPage':str(page),'section':section}]
menus={};screens={}
def node(id,title,parent=None,key=None,level=1,page=18,section='3.4',hint='',behavior='menu',summary='',**extra):
 n=dict(id=id,title=title,label=title,parentId=parent,key=key,accessLevel=level,access=('Customer Operator '+str(level) if level<8 else 'Customer Manager '+str(level-7)),sourceRefs=refs(page,section),hint=hint,summary=summary or hint,behavior=behavior,simulationStatus='reference-only' if behavior=='reference' else 'implemented',**extra)
 if behavior=='menu':n['entries']=[];menus[id]=n
 else:screens[id]=n
 if parent:menus[parent]['entries'].append(dict(key=key,label=title,target=id,accessLevel=level))
 return n
